1	/**
2	 * @fileoverview PaymentGatewayRawNotificationKyselyRepository
3	 *
4	 * Query-side (no aggregate) repository for
5	 * `payment_gateway_raw_notifications` — the redacted PayU webhook evidence
6	 * trail (Migration 266, TS-TOKEN-TOPUP-001 Faza 0, część A2).
7	 *
8	 * RP12-EXCEPTION: `payment_gateway_raw_notifications` has no aggregate/domain
9	 * port — it is a pure infrastructure evidence log, not a DDD aggregate. This
10	 * repository injects `DATABASE_TOKEN` directly (no `BaseKyselyRepository`,
11	 * no `LOGGER_SERVICE` — console.warn is the established convention for
12	 * repositories in this repo).
13	 *
14	 * Two write paths, per DEC21 (see BR-PAY-RAWNOTIF-WRITE-SAMPLING-001):
15	 *   - `recordVerifiedNotification()` — one full row per verified
16	 *     (`signature_valid = true`) request.
17	 *   - `recordFailedSignatureSample()` — sampled: one aggregated row per
18	 *     (source_ip_hash, hour_bucket) among unverified requests, upserted via
19	 *     `ON CONFLICT ... DO UPDATE` incrementing `attempt_count` against the
20	 *     partial unique index created by Migration 266.
21	 *
22	 * Both methods are best-effort/fire-and-forget on failure (catch +
23	 * console.warn, never throw) — the same precedent already used for
24	 * non-critical audit writes in this codebase (see
25	 * `SecurityOperationKyselyRepository.auditLockAcquisition/auditLockRelease`).
26	 * A raw-notification write failing must never block the webhook response or
27	 * (for verified notifications) payment completion — that would make this
28	 * evidence trail a new availability dependency for the money path, which is
29	 * a bigger design decision than this task authorizes (see the deferred TODO
30	 * in `PaymentsWebhookController` re: gating 2xx on durable persistence).
31	 *
32	 * @module Payment/Infrastructure/Repositories
33	 * @since TS-TOKEN-TOPUP-001
34	 */
35	
36	import { Inject, Injectable } from '@nestjs/common';
37	import type { Kysely } from 'kysely';
38	import { sql } from 'kysely';
39	
40	import type { Database } from '@shared/database/types/database.types';
41	import { DATABASE_TOKEN } from '@shared/database/tokens';
42	
43	import type { RedactedWebhookHeaders, RedactedWebhookPayload } from '../webhooks/payment-webhook-redaction.util';
44	import { toHourBucket } from '../webhooks/payment-webhook-redaction.util';
45	
46	export interface RecordVerifiedNotificationInput {
47	  readonly payloadSha256: string;
48	  readonly payloadRedacted: RedactedWebhookPayload;
49	  readonly headersRedacted: RedactedWebhookHeaders;
50	  readonly sourceIpHash: string;
51	  readonly sourceIpAllowlisted: boolean;
52	  readonly requestId: string | null;
53	  readonly receivedAt?: Date;
54	}
55	
56	export interface RecordFailedSignatureSampleInput {
57	  readonly payloadSha256: string;
58	  readonly payloadRedacted: RedactedWebhookPayload;
59	  readonly headersRedacted: RedactedWebhookHeaders;
60	  readonly sourceIpHash: string;
61	  readonly sourceIpAllowlisted: boolean;
62	  readonly requestId: string | null;
63	  readonly receivedAt?: Date;
64	}
65	
66	@Injectable()
67	export class PaymentGatewayRawNotificationKyselyRepository {
68	  // RP12-EXCEPTION: no aggregate/domain port exists for this table — pure
69	  // infrastructure evidence log, DATABASE_TOKEN injected directly.
70	  constructor(@Inject(DATABASE_TOKEN) private readonly db: Kysely<Database>) {}
71	
72	  /**
73	   * Persist one full row for a notification whose signature was verified
74	   * (`signature_valid = true`). Never throws — logs and swallows on failure.
75	   */
76	  async recordVerifiedNotification(input: RecordVerifiedNotificationInput): Promise<void> {
77	    const receivedAt = input.receivedAt ?? new Date();
78	
79	    try {
80	      await this.db
81	        .insertInto('payment_gateway_raw_notifications')
82	        .values({
83	          payload_sha256: input.payloadSha256,
84	          payload_redacted: input.payloadRedacted as unknown as Record<string, unknown>,
85	          headers_redacted: input.headersRedacted as unknown as Record<string, unknown>,
86	          signature_valid: true,
87	          received_at: receivedAt,
88	          hour_bucket: toHourBucket(receivedAt),
89	          source_ip_hash: input.sourceIpHash,
90	          source_ip_allowlisted: input.sourceIpAllowlisted,
91	          request_id: input.requestId,
92	          attempt_count: 1,
93	        })
94	        .execute();
95	    } catch (error: unknown) {
96	      // Fire-and-forget: same precedent as SecurityOperationKyselyRepository
97	      // audit writes — a raw-notification write failure must not block
98	      // payment completion for a verified webhook.
99	      console.warn(
100	        '[PaymentGatewayRawNotificationKyselyRepository] Failed to record verified notification',
101	        { errorType: error instanceof Error ? error.constructor.name : typeof error }
102	      );
103	    }
104	  }
105	
106	  /**
107	   * DEC21 sampling: upsert an aggregated row for a notification whose
108	   * signature FAILED verification (`signature_valid = false`), keyed on
109	   * (source_ip_hash, hour_bucket). Increments `attempt_count` and refreshes
110	   * the redacted payload/headers/received_at to the latest attempt on
111	   * conflict. Never throws — logs and swallows on failure.
112	   */
113	  async recordFailedSignatureSample(input: RecordFailedSignatureSampleInput): Promise<void> {
114	    const receivedAt = input.receivedAt ?? new Date();
115	    const hourBucket = toHourBucket(receivedAt);
116	
117	    try {
118	      await this.db
119	        .insertInto('payment_gateway_raw_notifications')
120	        .values({
121	          payload_sha256: input.payloadSha256,
122	          payload_redacted: input.payloadRedacted as unknown as Record<string, unknown>,
123	          headers_redacted: input.headersRedacted as unknown as Record<string, unknown>,
124	          signature_valid: false,
125	          received_at: receivedAt,
126	          hour_bucket: hourBucket,
127	          source_ip_hash: input.sourceIpHash,
128	          source_ip_allowlisted: input.sourceIpAllowlisted,
129	          request_id: input.requestId,
130	          attempt_count: 1,
131	        })
132	        .onConflict(oc =>
133	          oc
134	            .columns(['source_ip_hash', 'hour_bucket'])
135	            .where('signature_valid', '=', false)
136	            .doUpdateSet({
137	              received_at: receivedAt,
138	              request_id: input.requestId,
139	              payload_sha256: input.payloadSha256,
140	              payload_redacted: input.payloadRedacted as unknown as Record<string, unknown>,
141	              headers_redacted: input.headersRedacted as unknown as Record<string, unknown>,
142	              source_ip_allowlisted: input.sourceIpAllowlisted,
143	              attempt_count: sql`payment_gateway_raw_notifications.attempt_count + 1`,
144	            })
145	        )
146	        .execute();
147	    } catch (error: unknown) {
148	      console.warn(
149	        '[PaymentGatewayRawNotificationKyselyRepository] Failed to record failed-signature sample',
150	        { errorType: error instanceof Error ? error.constructor.name : typeof error }
151	      );
152	    }
153	  }
154	}
