1	/**
2	 * @fileoverview PayU Webhook Redaction Utilities
3	 *
4	 * Pure, deterministic helpers that turn a raw PayU webhook request (payload +
5	 * HTTP headers) into the redacted shapes persisted by
6	 * `payment_gateway_raw_notifications` (Migration 266,
7	 * TS-TOKEN-TOPUP-001 Faza 0, część A2). No I/O, no NestJS DI — safe to unit
8	 * test directly (see the frozen-key-set guardian in
9	 * `__tests__/payment-webhook-redaction.util.guardian.spec.ts`, owned by
10	 * @test-implementer).
11	 *
12	 * Two independent allowlists live here, both explicit (never a blocklist):
13	 *   - `toRedactedPayload()` — payload field allowlist (ADR-0021 format
14	 *     validation happens upstream via `payuWebhookPayloadSchema`; this is a
15	 *     SEPARATE, narrower allowlist for what is safe to durably persist).
16	 *   - `toRedactedHeaders()` — header field allowlist. Anything not in the
17	 *     frozen 8-field set (cookie, authorization, x-forwarded-for, ...) is
18	 *     silently dropped and only contributes to `unknownHeaderCount`, which is
19	 *     NOT persisted (keeps the stored shape exactly 8 keys) — it exists for
20	 *     the caller to log/alert on if desired.
21	 *
22	 * @module Payment/Infrastructure/Webhooks
23	 * @since TS-TOKEN-TOPUP-001
24	 */
25	
26	import { createHash } from 'crypto';
27	
28	import { hashIdentifier } from '@shared/utils/crypto.utils';
29	import type { PayuWebhookPayload } from '@shared/validation/schemas/payments';
30	
31	// ============================================================================
32	// PAYLOAD REDACTION
33	// ============================================================================
34	
35	/**
36	 * Allowlisted, persisted projection of a PayU webhook payload.
37	 *
38	 * Deliberately excludes `order.customerIp` (PII — the source IP is captured
39	 * separately, hashed, as `source_ip_hash`) and `properties[]` (arbitrary
40	 * provider-supplied key/value pairs with no fixed schema — cannot be safely
41	 * allowlisted field-by-field).
42	 */
43	export interface RedactedWebhookPayload {
44	  readonly orderId: string;
45	  readonly extOrderId: string | null;
46	  readonly status: string;
47	  readonly totalAmount: string | null;
48	  readonly currencyCode: string | null;
49	  readonly localReceiptDateTime: string | null;
50	}
51	
52	/**
53	 * Project a validated PayU webhook payload down to the allowlisted fields
54	 * safe to persist in `payment_gateway_raw_notifications.payload_redacted`.
55	 *
56	 * @param payload - already Zod-validated (`payuWebhookPayloadSchema`) payload
57	 */
58	export function toRedactedPayload(payload: PayuWebhookPayload): RedactedWebhookPayload {
59	  return {
60	    orderId: payload.order.orderId,
61	    extOrderId: payload.order.extOrderId ?? null,
62	    status: payload.order.status,
63	    totalAmount: payload.order.totalAmount ?? null,
64	    currencyCode: payload.order.currencyCode ?? null,
65	    localReceiptDateTime: payload.localReceiptDateTime ?? null,
66	  };
67	}
68	
69	/**
70	 * sha256 hex digest of the raw (pre-parse) webhook body.
71	 *
72	 * Stored as `payload_sha256` — lets us detect byte-identical retries/replays
73	 * without storing the raw body itself (which could contain
74	 * `order.customerIp`/`properties[]`).
75	 */
76	export function computePayloadSha256(rawBody: string): string {
77	  return createHash('sha256').update(rawBody).digest('hex');
78	}
79	
80	// ============================================================================
81	// HEADER REDACTION
82	// ============================================================================
83	
84	/**
85	 * Exactly the 8 fields persisted in
86	 * `payment_gateway_raw_notifications.headers_redacted`. Frozen set — do not
87	 * add fields without updating the guardian test and this docblock together.
88	 */
89	export interface RedactedWebhookHeaders {
90	  readonly openpayu_sig_sender: string | null;
91	  readonly openpayu_sig_algorithm: string | null;
92	  readonly openpayu_sig_value: string | null;
93	  readonly openpayu_sig_content: string | null;
94	  readonly content_type: string | null;
95	  readonly content_length: string | null;
96	  readonly user_agent: string | null;
97	  readonly provider_date: string | null;
98	}
99	
100	/** Node/Express normalizes incoming header names to lowercase. */
101	export type IncomingHeadersLike = Record<string, string | string[] | undefined>;
102	
103	const USER_AGENT_MAX_LENGTH = 256;
104	
105	/**
106	 * The 8 raw header names this allowlist reads from. Everything else on the
107	 * request (cookie, authorization, x-forwarded-for, ...) is ignored and only
108	 * counted in `unknownHeaderCount`.
109	 *
110	 * `openpayu-signature` is PayU's single composite header, formatted as
111	 * semicolon-separated `key=value` pairs (`signature=...;algorithm=...;
112	 * sender=...;content=DOCUMENT`) — parsed into 4 of the 8 output fields below.
113	 */
114	const KNOWN_RAW_HEADER_NAMES = new Set([
115	  'openpayu-signature',
116	  'content-type',
117	  'content-length',
118	  'user-agent',
119	  // GAP: no confirmed PayU-specific date header name exists in this repo's
120	  // docs/security/rules/ today. `date` is the standard HTTP response/request
121	  // date header and the closest available signal for `provider_date` — flag
122	  // for confirmation against PayU's actual notification headers before
123	  // relying on this field for anything beyond forensics.
124	  'date',
125	]);
126	
127	function firstValue(value: string | string[] | undefined): string | null {
128	  if (value === undefined) return null;
129	  return Array.isArray(value) ? (value[0] ?? null) : value;
130	}
131	
132	/**
133	 * Parse PayU's composite `OpenPayu-Signature` header
134	 * (`signature=...;algorithm=...;sender=...;content=DOCUMENT`) into its
135	 * components. Unknown/missing components are `null`, never thrown.
136	 */
137	function parseOpenPayuSignatureHeader(headerValue: string | null): {
138	  sender: string | null;
139	  algorithm: string | null;
140	  value: string | null;
141	  content: string | null;
142	} {
143	  if (!headerValue) {
144	    return { sender: null, algorithm: null, value: null, content: null };
145	  }
146	
147	  const parts = new Map<string, string>();
148	  for (const segment of headerValue.split(';')) {
149	    const eqIndex = segment.indexOf('=');
150	    if (eqIndex === -1) continue;
151	    const key = segment.slice(0, eqIndex).trim().toLowerCase();
152	    const val = segment.slice(eqIndex + 1).trim();
153	    if (key) parts.set(key, val);
154	  }
155	
156	  return {
157	    sender: parts.get('sender') ?? null,
158	    algorithm: parts.get('algorithm') ?? null,
159	    value: parts.get('signature') ?? null,
160	    content: parts.get('content') ?? null,
161	  };
162	}
163	
164	/**
165	 * Redact incoming HTTP headers down to the frozen 8-field allowlist.
166	 *
167	 * @param headers - raw `req.headers` (Express normalizes names to lowercase)
168	 * @returns `headers` — exactly the 8 allowlisted fields (persisted as-is to
169	 *   `headers_redacted`) — and `unknownHeaderCount` — number of header names
170	 *   NOT in the allowlist, for the caller to log/alert on; deliberately NOT
171	 *   included in `headers` itself (would break the frozen 8-key contract).
172	 */
173	export function toRedactedHeaders(headers: IncomingHeadersLike): {
174	  headers: RedactedWebhookHeaders;
175	  unknownHeaderCount: number;
176	} {
177	  const sig = parseOpenPayuSignatureHeader(firstValue(headers['openpayu-signature']));
178	  const userAgent = firstValue(headers['user-agent']);
179	
180	  const redacted: RedactedWebhookHeaders = {
181	    openpayu_sig_sender: sig.sender,
182	    openpayu_sig_algorithm: sig.algorithm,
183	    openpayu_sig_value: sig.value,
184	    openpayu_sig_content: sig.content,
185	    content_type: firstValue(headers['content-type']),
186	    content_length: firstValue(headers['content-length']),
187	    user_agent: userAgent ? userAgent.slice(0, USER_AGENT_MAX_LENGTH) : null,
188	    provider_date: firstValue(headers['date']),
189	  };
190	
191	  const unknownHeaderCount = Object.keys(headers).filter(
192	    name => !KNOWN_RAW_HEADER_NAMES.has(name.toLowerCase())
193	  ).length;
194	
195	  return { headers: redacted, unknownHeaderCount };
196	}
197	
198	// ============================================================================
199	// SOURCE IP
200	// ============================================================================
201	
202	/**
203	 * `source_ip_hash` — `hashIdentifier(clientIp)` (ANONYMIZATION_SALT), never a
204	 * raw IP address (SI5). `clientIp` MUST come from
205	 * `SecureIPExtractorService.extractSecureClientIP()` (spoofing-resistant),
206	 * not read directly off a header — `hashIdentifier()` only does the hashing
207	 * half of this, extraction is a separate, prior step done by the caller.
208	 */
209	export function hashSourceIp(clientIp: string): string {
210	  return hashIdentifier(clientIp);
211	}
212	
213	/**
214	 * Whether `clientIp` falls within a configured PayU webhook source-IP
215	 * allowlist (CIDR /24 match, same technique as
216	 * `SmsApiIpGuard.isInCidr24()` — TS-SMS-002).
217	 *
218	 * GAP (TS-TOKEN-TOPUP-001 Faza 0, część A2): no PayU webhook source-IP
219	 * allowlist exists in `docs/security/rules/` or `ConfigService` today — this
220	 * is a security parameter that must be sourced from
221	 * `docs/security/rules/rate-limiting-abuse.md` (or a decision from
222	 * @security-privacy-architect), not invented here. Until that parameter
223	 * exists, callers pass `[]` and every request is `source_ip_allowlisted:
224	 * false`. The column is written from day one so no backfill is needed once
225	 * the range list lands.
226	 */
227	export function isSourceIpAllowlisted(clientIp: string, allowlistRangesCidr24: readonly string[]): boolean {
228	  if (allowlistRangesCidr24.length === 0) return false;
229	
230	  const normalizedIp = clientIp.replace(/^::ffff:/i, '');
231	  const ipParts = normalizedIp.split('.');
232	  if (ipParts.length !== 4) return false;
233	
234	  return allowlistRangesCidr24.some(cidr => {
235	    const [networkAddress] = cidr.split('/');
236	    if (!networkAddress) return false;
237	    const netParts = networkAddress.split('.');
238	    if (netParts.length !== 4) return false;
239	    return ipParts[0] === netParts[0] && ipParts[1] === netParts[1] && ipParts[2] === netParts[2];
240	  });
241	}
242	
243	// ============================================================================
244	// HOUR BUCKET (DEC21 sampling key)
245	// ============================================================================
246	
247	/**
248	 * Truncate a timestamp to the start of its hour (UTC) — the `hour_bucket`
249	 * half of the DEC21 `(source_ip_hash, hour_bucket)` sampling key for
250	 * `signature_valid = false` rows.
251	 */
252	export function toHourBucket(receivedAt: Date): Date {
253	  const bucket = new Date(receivedAt);
254	  bucket.setUTCMinutes(0, 0, 0);
255	  return bucket;
256	}
